"""Four-application aggregation. Trajectory answers are generated by engine.py."""
import argparse
import hashlib
import json
import math
import sys
import time
from pathlib import Path


def digest(path):
    h = hashlib.sha256()
    with Path(path).open('rb') as f:
        for block in iter(lambda: f.read(1024 * 1024), b''):
            h.update(block)
    return h.hexdigest()


def read(path):
    return json.loads(Path(path).read_text(encoding='utf-8-sig'))


def probability(value):
    if isinstance(value, bool) or not isinstance(value, (float, int)):
        raise ValueError('Score must be a number')
    # The original sum can exceed one by one floating-point ulp. Preserve it.
    if not math.isfinite(value) or not -1e-12 <= value <= 1 + 1e-12:
        raise ValueError('Non-finite or out-of-range score')
    return value


def indexed(rows, key, expected):
    result = {}
    for row in rows:
        k = key(row)
        if k in result:
            raise ValueError('Duplicate question: ' + str(k))
        result[k] = row
    if set(result) != set(expected) or not result:
        raise ValueError('Answers must include exactly the frozen questions, including missing answers')
    return result


def weighted(rows):
    total = 0
    numerator = 0.0
    for row in rows:
        weight = row['real_support']
        support = row['synthetic_support']
        if type(weight) is not int or weight <= 0 or type(support) is not int or support < 0:
            raise ValueError('Invalid query support')
        score = probability(row['score'])
        if not support and score != 0:
            raise ValueError('Missing answer must score zero')
        total += weight
        numerator += weight * score
    return numerator / total


def aggregate(questions, details):
    mfp = indexed(details['mfp'], lambda r: r['query_id'],
                  [r['query_id'] for r in questions['mfp_queries']])
    roads = indexed(details['selected_road'], lambda r: r['road'], questions['selected_roads'])
    turns = indexed(details['turning'], lambda r: (r['junction'], r['incoming']),
                    [tuple(r) for r in questions['turning_incoming']])
    for row in mfp.values():
        if row['status'] != 'ANSWER' and row['ordered_length_overlap'] != 0:
            raise ValueError('Missing MFP answer must score zero')
    k = questions['representative']['K']
    rep = details['representative'][str(k)]
    covered, population, actual = rep['covered'], rep['population'], rep['actual_routes']
    if (type(population) is not int or population <= 0 or type(covered) is not int
            or not 0 <= covered <= population or type(actual) is not int or not 0 <= actual <= k
            or population != questions['representative']['real_population']):
        raise ValueError('Invalid representative coverage denominator or route budget')
    if actual == 0 and covered:
        raise ValueError('No representative route cannot cover real trips')
    coverage = covered / population
    if not math.isclose(probability(rep['score']), coverage, abs_tol=1e-12):
        raise ValueError('Representative stored score disagrees with covered/population')
    return {
        'MFPOrderedRouteOverlap': sum(probability(r['ordered_length_overlap']) for r in mfp.values()) / len(mfp),
        'RepresentativeRealCoverage': coverage,
        'SelectedRoadMarginalOverlap': weighted(roads.values()),
        'IncomingExitDistributionOverlap': weighted(turns.values()),
    }


def evaluate(questions_path, answers, out):
    started = time.perf_counter()
    q = read(questions_path)
    manifest = read(answers / 'manifest.json')
    if q['status'] != 'LOCKED_REAL_ONLY' or manifest['status'] != 'COMPLETE':
        raise ValueError('Require locked questions and completed answers')
    if manifest['questions_sha256'] != digest(questions_path):
        raise ValueError('Answers use different questions')
    details_path = answers / 'details.json'
    if manifest['outputs']['details.json'] != digest(details_path):
        raise ValueError('Answer details changed')
    metrics = aggregate(q, read(details_path))
    out.mkdir(parents=True, exist_ok=False)
    result = dict(method=manifest['method'], metrics=metrics,
                  metric_status={k: 'ZERO' if v == 0 else 'VALID' for k, v in metrics.items()},
                  scope='retrospective_four_road_applications',
                  protocol='supported_questions_20261102',
                  normalization='direct score; missing answers zero; no Real-train division')
    (out / 'metrics.json').write_text(json.dumps(result, ensure_ascii=False, indent=2, allow_nan=False), encoding='utf-8')
    receipt = dict(status='COMPLETE', dataset_id=q['dataset_id'], method=manifest['method'],
                   questions_sha256=digest(questions_path), answer_manifest_sha256=digest(answers / 'manifest.json'),
                   details_sha256=digest(details_path), source_sha256=digest(__file__),
                   result_sha256=digest(out / 'metrics.json'), argv=sys.argv,
                   seconds=time.perf_counter() - started,
                   validation_scope='score aggregation only; not raw-trajectory end-to-end')
    (out / 'manifest.json').write_text(json.dumps(receipt, ensure_ascii=False, indent=2), encoding='utf-8')
    print(json.dumps(result, ensure_ascii=False), flush=True)


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--questions', type=Path, required=True)
    parser.add_argument('--answers', type=Path, required=True)
    parser.add_argument('--out', type=Path, required=True)
    args = parser.parse_args()
    evaluate(args.questions, args.answers, args.out)
